func (q *Queries) ReceiptLineByBatch(ctx context.Context, arg ReceiptLineByBatchParams) ([]ReceiptLineByBatchRow, error) {
	rows, err := q.db.Query(ctx, receiptLineByBatch, arg.ProductID, arg.BatchID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ReceiptLineByBatchRow
	for rows.Next() {
		var i ReceiptLineByBatchRow
		if err := rows.Scan(&i.ID, &i.PurchaseOrderID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

