const totalOpenGRNI = `-- name: TotalOpenGRNI :one
SELECT coalesce(sum(l.grni_amount - l.billed_grni_amount - l.returned_grni_amount), 0)::numeric AS total
FROM goods_receipt_lines l
JOIN goods_receipts r ON r.id = l.goods_receipt_id
WHERE r.status = 'posted'
`

// Total saldo Barang Diterima Belum Ditagih seluruh GR (pembanding saldo akun 2102).
func (q *Queries) TotalOpenGRNI(ctx context.Context) (decimal.Decimal, error) {
	row := q.db.QueryRow(ctx, totalOpenGRNI)
	var total decimal.Decimal
	err := row.Scan(&total)
	return total, err
}

const updateGoodsReceipt = `-- name: UpdateGoodsReceipt :execrows
UPDATE goods_receipts
SET number = $1, business_date = $2, location_id = $3,
    toll_location_id = $4, delivery_note_number = $5,
    note = $6, inventory_amount = $7,
    material_amount = $8, grni_amount = $9, status = $10,
    inbound_id = $11, journal_entry_id = $12,
    reversal_journal_entry_id = $13, cancel_reason = $14,
    posted_at = $15, cancelled_at = $16,
    updated_at = now(), updated_by = $17, version = version + 1
WHERE id = $18 AND version = $19
`

type UpdateGoodsReceiptParams struct {
	Number                 pgtype.Text
	BusinessDate           clock.BusinessDate
	LocationID             uuid.UUID
	TollLocationID         uuid.NullUUID
	DeliveryNoteNumber     string
	Note                   string
	InventoryAmount        decimal.Decimal
	MaterialAmount         decimal.Decimal
	GrniAmount             decimal.Decimal
	Status                 string
	InboundID              uuid.NullUUID
	JournalEntryID         uuid.NullUUID
	ReversalJournalEntryID uuid.NullUUID
	CancelReason           string
	PostedAt               *time.Time
	CancelledAt            *time.Time
	ActorID                uuid.UUID
	ID                     uuid.UUID
	Version                int32
}

func (q *Queries) UpdateGoodsReceipt(ctx context.Context, arg UpdateGoodsReceiptParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateGoodsReceipt,
		arg.Number,
		arg.BusinessDate,
		arg.LocationID,
		arg.TollLocationID,
		arg.DeliveryNoteNumber,
		arg.Note,
		arg.InventoryAmount,
		arg.MaterialAmount,
		arg.GrniAmount,
		arg.Status,
		arg.InboundID,
		arg.JournalEntryID,
		arg.ReversalJournalEntryID,
		arg.CancelReason,
		arg.PostedAt,
		arg.CancelledAt,
		arg.ActorID,
		arg.ID,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

